// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    StaxLPStaking c;

    function setUp() public {
        c = new StaxLPStaking(address(this), address(this));
    }

    function _run(address newMigrator) internal {
        try c.setMigrator(newMigrator) {} catch { return; }
        address observed;
        try c.migrator() returns (address __r) { observed = __r; } catch { return; }
        assertTrue(observed == newMigrator);
    }

    function testFuzz_run(address newMigrator) public {
        _run(newMigrator);
    }

    receive() external payable {}
}
